        check(Printers::remove_named_printer(*m_plater, nullptr, "Shed Neo").empty() &&
                  printer_profile("Shed Neo") == nullptr && selected_printer() == kAddedPrinterProfile,
              "named_remove_of_the_selected_printer_selects_its_parent");
        verify_named_header();
